          + 'lentokohtaus juhlavammaksi: paksumpi katkoviivareitti, '
          + 'saapumisleima, harsopilvet hitaasti kartan yli.',
        'AVAUSLENTO VALMIIKSI LADATTUNA (omistaja 3.9.2026, kaappaus '
          + 'Lontoo-Sarajevo: "kartta pitaa ladata etukateen, nyt se '
          + 'rakentui pikkuhiljaa taustalla valmiiksi. lisaksi muiden '
          + 'kaupunkien kuin lontoon ja kohdekaupungin nimia ei tarvita. '
          + 'jostain syysta myos kertojan aani jai kuulumattomiin vaikka '
          + 'kohdekaupungissa kylla sitten taas kuului."): 1) lentokartan '
          + 'laatat ja nimikerros ladataan ja piirretaan VALMIIKSI ennen '
          + 'kuin lento alkaa (etukateispuskuri; feidi vasta valmiiseen '
          + 'karttaan); 2) lentokohtauksessa nakyvat vain LONTOON ja '
          + 'KOHDEKAUPUNGIN nimet - muut kaupunki- ja maastonimet '
          + 'piilotetaan lennon ajaksi; 3) kertojan luenta (lennon '
          + 'kaaritekstit) kuuluu myos lentokohtauksessa - vika '
          + 'selvitetaan ja korjataan. TOTEUTETTU v1492: laattojen odotus '
          + '(odotaPyramidi, katto 6 s), nimikerroksen lentotila, ja luenta '
          + 'lahtee kohtauksesta laattojen valmistuttua. Juurisyy: luenta '
          + 'oli kiintean 2,3 s ajastimen varassa, joka osui laattojen '
          + 'latauksen paalle ja peruuntui lennon paattyessa.',
        'SAAPUMISSEKVENSSI (omistaja 26.8.2026, sanamuodot kaanon): '
          + 'lennon jälkeen feidi tyhjään pergamenttiin → '
          + 'konekirjoitettu välikortti "<KAUPUNKI> · PÄIVÄ <n>/80" '
          + '→ kartta feidautuu suoraan oikeaan zoomiin ILMAN ajoa '
