          + 'TÄKYANNOSTELU: ruudulla korkeintaan YKSI täkykupla '
          + 'kerrallaan; muut täyt näkyvät kartalla heti '
          + 'SYMBOLEINA (huutomerkki = skandaali/hurja, '
