          + 'ennen. (5) VIRTUAALIKIERROSIKKUNA: ulkoinen kierros '
          + 'saa aueta pelin sisäiseen ikkunaan vain jos sivusto ei '
          + 'estä upotusta EIKÄ KIELLÄ sitä ehdoissaan; muuten '
          + 'linkkinä laitteen selaimeen (avaustapa on datassa, '
          + 'oletus linkki). TARKENNUS (omistaja 26.8.2026 ilta): '
          + 'kierros otetaan peliin VAIN jos se aukeaa pelin sisällä '
          + '— acropolisvirtualtour.gr jäi siksi kokonaan pois '
          + '(ministeriön ehdot kieltävät kehystämisen), ja tilalle '
          + 'tulivat Akropolis-museon KOLME Google Arts & Culture '
          + '-upotusta (Parthenon-galleria, rinteet, kaivaus museon '
          + 'alla; museo julkaisee embed-osoitteet itse, joten upotus '
          + 'on sekä sallittu että tarkoitettu). (6) AARTEEN PALJASTUS '
          + 'mustalla pohjalla + JATKA MATKAA -nappi; "taskuun"-rivi '
          + 'pois toistaiseksi. (7) ÄÄNIVALIKKO erittelee KERTOJAN '
          + 'ja TAUSTAÄÄNET; matkakirjan kaiutinnappi synkassa '
          + 'hampurilaisvalikon kytkimen kanssa, pysyvä valinta. '
          + '(8) LEHTIVINKKI: viive ~1,4 s, teksti "Etsi minitehtävä '
          + 'lehdestä ja ratkaise se, niin saat vinkin aarteen '
          + 'paikasta kartalla." + suora linkki lehden oikeaan '
          + 'kappaleeseen; aarrekuittaus "Aarteen jälki syttyi: '
          + 'vihreä piste kartalla näyttää paikan." ~2,5 s viiveellä.',
        'LIVIAN AVAUSESITTELY (omistaja 29.8.2026): Livia tulee mukaan '
          + 'HETI ALOITUSVALINNASSA - kun ensimmainen karttaikkuna aukeaa '
          + '(se nakyma, josta pelaaja valitsee ensimmaisen lentonsa '
          + 'kohteen), Livia lennahtaa paikalle ja esittaytyy '
          + 'kuplasarjalla. BETA-RAJOITUS KERROTAAN TARINAN SISALLA: '
          + 'valittavana on toistaiseksi yksi reitti, ja se sanotaan '
          + 'niin etta pollo on ehtinyt tarkistaa vasta yhden reitin - '
          + 'sanaa "beta" ei kayteta. Repliikit ovat KAANONIA (nelja '
          + 'kuplaa: sinahan olet ihan hiessa / mina olen Livia ja '
          + 'kannoin ne sahkeet / valitse rauhassa mista aloitat - '
          + 'vaikka se maanosa joka kutkuttaa eniten / anteeksi '
          + 'valikoima, Ateenasta se alkaa / perilla sinua odottaa Viisas '
          + 'Pollo, mina olen vain viestinvieja). Sarja naytetaan KERRAN '
          + 'PER LAITE, eivatka kuplat esta valintaa: kaupungin voi '
          + 'napauttaa milloin vain, jolloin kuplat vaistyvat. '
          + 'ENSISAAPUMISEN TUURAUSPALJASTUS: avaus lupaa pollon '
          + 'oppaaksi ja Livian pelkaksi viestinviejaksi, ja perilla '
          + 'ensimmaisessa kohdemaassa (Ateena beta-rajauksessa) '
          + 'selviaa etta pollo on juuttunut matkoilleen - Livia '
          + 'joutuukin tuuraamaan. Kahden kuplan sarja (Kaak, sahke, '
          + 'pollo on juuttunut, mina tuuraan / ei hataa, olen kantanut '
          + 'sen sahkeet vuosia ja lukenut joka ikisen, melkein joka '
          + 'ikisen, aloitetaan) tulee normaalin maadoituskuplan '
          + 'TILALLA ja vain ensimmaisella saapumisella koskaan; '
          + 'seuraavat saapumiset kulkevat normaalisti. Nain '
          + 'sijaisuustarina muuttuu taustatiedosta pelaajan kokemaksi '
          + 'hetkeksi - repliikit ovat kaanonia molemmissa paissa. MYOS '
          + 'MANNERIVIHJE: kun pelaaja on jaanyt samaan maahan pitkaksi '
          + 'aikaa aarteen loydyttya ja rahaa on kertynyt, Livia '
          + 'muistuttaa kerran etta isosta kaupungista paasee toiselle '
          + 'mantereelle. Laukaisin on TILANTEESTA, ei kalenterista, '
          + 'eika vihje koskaan vaheksy sita sisaltoa jonka aarella '
          + 'pelaaja viipyy.',
        'PULU-KOKEILU (omistaja 27.8.2026, idea vaimolta): Viisas Pollo '
          + 'korvataan KOKEILUNA kirjekyyhkyhahmolla KEVYENA '
          + 'VALIVERSIONA pelitestia varten. Hahmo: LIVIA, taydelta '
          + 'nimeltaan Columba Livia (kalliokyyhkyn tieteellinen nimi - '
          + '"suku on vanhaa roomalaista" on totta). Tausta 1873: isoaiti '
          + 'lensi Pariisin piirityksen kyyhkypostia 1870-71, seta kantoi '
          + 'kursseja Reuterille ennen lennatinta. AANI: aidosti '
          + 'asiantunteva viestinvieja joka puolustautuu refleksina '
          + '(sukua ei arvosteta) - komiikka arvostuksen puutteesta, EI '
