          + 'localStorage sailyvat polloasuisina kunnes pelitesti '
          + 'ratkaisee jatkon (taysvaihto / pollo takaisin / pari). '
          + 'Ateenan pikkupollo-karttakohde on faktasisaltoa ja sailyy.',
        'REAKTIOJARJESTELMA (omistaja 28.8.2026: koko alkuperainen '
          + 'suunnitelma kayttoon): viisi kaiverrettua symbolia - '
          + 'laakeriseppele (Hieno), sydan (Ihana), suurennuslasi '
          + '(Mielenkiintoinen), tiimalasi (Tylsa), mustetahra (Virhe). '
          + 'Rivi jokaisessa sisallossa (lehtijutut, kohdekortit, '
          + 'nahtavyydet, ihmeet) JA lehtien valiotsikoissa (otsikko:-'
