          + 'Lepotila = yksi himmea nappi (voittajasymboli + maara), '
          + 'napautus levittaa viisi symbolia. Laskurit ovat JAETTUJA: '
          + 'ehdotuskanavan worker sailoo aanet R2:een (reaktiot/-'
          + 'etuliite, ehdollinen kirjoitus, EI laitetunnistetta eika '
          + 'IP:ta), 1 aani/laite/kohde (localStorage), vaihdettavissa '
          + 'ja peruttavissa. Vain mustetahra kysyy vapaatekstin '
          + '(minipopup) ja lahettaa sen vanhaa /laheta-reittia '
          + 'Lukijoilta-lehdelle; tahran jalkeen Livian nolo kiitos. '
          + 'Tyohuoneessa Reaktiot- ja Virheilmoitukset-sivut; "Merkitse '
          + 'korjatuksi" nollaa tahralaskurin ja tahra haviaa pelaajilta. '
          + 'Ei koskaan blokkaa pelaamista; laskurihaku vasta napin '
          + 'avautuessa. Symbolikuvat viela valiaikaiset viivaikonit - '
          + 'lopulliset generoidaan symboliputkella (vaihtuu vain 5 '
          + 'polkuvakiota). Jatkotyo: sama rivi Livian chat-vastauksiin.',
        'MOTIVAATIOTEORIA ON PELIN YDIN (omistaja 28.8.2026 aamu, '
          + 'TARKEA): peli hyodyntaa motivaatioteoriaa siita, miten eri '
          + 'ihmiset kiinnostuvat eri asioista - ja se on taman pelin '
          + 'ydin. EI opiskella suoraan "mika on Makedonia", vaan '
          + 'lahdetaan liikkeelle vaikka siita mita siella syodaan ja '
          + 'mika on paikallinen herkkuruoka (eli pulla). Kun kiinnostus '
