          + 'osiin. Pulla ja pulu kulkevat maasta toiseen taman '
          + 'periaatteen kantajina. Kirjataan myos pelin julkiseen '
          + 'esittelyyn (README).',
        'LIVIA PYSYVAKSI JA PULLA-PERSOUS (omistaja 28.8.2026 aamu: '
          + '"otetaan siis pulu nyt talla uudella roolilla kayttoon '
          + 'pysyvasti"): pulukokeilu paattyy - Livia on pysyva. '
