          + 'latinankielisella nimellaan Columba Livia. Chatissa '
          + 'jokainen vastaus alkaa parin sanan hopotyksella ("Niin,", '
          + '"Annas kun mietin.", "Nyt muistan:" - lyhyita, vaihtelevia).',
        'PULLAVINKKI AARRETEHTAVASSA (omistaja 28.8.2026 aamu): '
          + 'aarretehtavan vinkin voi jatkossa saada myos OSTAMALLA '
          + 'PULLAN PULULLE pelin punnilla - pullan nimi on maan oma '
          + 'pullavastine (tsoureki, kozunak, simit...). Halvempi kuin '
          + 'matkalippu, kerran per aarre.',
        'LIVIA JALKIKOMMENTAATTORINA (omistaja 28.8.2026 aamu): aina '
          + 'kun isoisan matkakirjamerkinnan tarina loppuu, Livia saa '
          + 'kommentoida jotain lisaksi - maadoitus, kansallisherkku, '
          + 'paikallinen pukeutuminen (TESTAAMATON KOKEILU, omistaja '
          + '28.8.2026 ilta: "vain heitetty idea, en tieda miten se '
          + 'kaytannossa toimii" - kokeillaan korkeintaan yhdessa '
          + 'kaupungissa ennen laajempaa kayttoa), sukutarina tai se mita on '
          + 'tapahtunut 1873:n ja nykyhetken valissa (Livia nakee ajan '
