          + 'kupla per saapuminen. TARKEA MITOITUS: taman takia isoisan '
          + 'omat merkinnat pidetaan lyhyina, jotta yhteismitta ei '
          + 'kasva liikaa.',
        'LIVIAN PUHEKIELI - TYYLIMAARITTELY (omistaja 28.8.2026 ilta, '
          + 'tehty yhdessa korteilla; TARKEA - "pelin kannalta todella '
          + 'tarkea saada toimimaan oikein"): Livia puhuu AINA '
          + 'puhekielta, ei koskaan kirjakielta. Kolme saantoa: '
          + '1) PAINOPISTE REUNOILLA (tasmennys 28.8.2026 ilta 2, '
          + 'omistajan kortti): loppuheitot ja lyhentymat (mut, siit, '
          + 'sillon, viiskyt, tosta) vain tekstin ALUSSA ja LOPUSSA - '
          + 'juuri niissa kohdissa jotka ovat Livian omaa aanta '
          + 'kehysmallissakin. KESKELLA puheen rytmi ja arkisanasto '
          + 'sailyvat mutta sanat kirjoitetaan auki (mutta, silloin, '
          + 'sataviisikymmenta) - avatut sanat lukevat kevyemmin '
          + 'pitkassa tekstissa ja lukijaaani lausuu ne paremmin; '
          + 'enintaan yksi lyhentyma keskella tehokeinona; '
          + '2) PRONOMINIT KOKONAISINA: mina/sina, EI ma/sa - '
          + 'proystea kirjekyyhky sanoo mina vaikka puhuu muuten '
          + 'rennosti; 3) KEVYET TAYTESANAT saastellen (no, niin, kato, '
          + 'hei) ja Kaak-lintuaanne VAIN aidoissa saikahdyksissa. '
          + 'Kirjakielinen abstraktio ("se asettaa sen kauas") on VIRHE '
          + 'Livian suussa. Tavoite: nokkelaa, hauskaa ja monitasoista '
          + '- Livia on vastapaino kaikelle tiedolle ja raskaalle '
          + 'sisallolle, se yllattava elementti josta pelaaja kertoo '
          + 'kaverilleen ("se pulu on tosi hauska tyyppi"). Puhe '
          + 'pidetaan paalla joka paikassa; karsitaan vasta jos '
          + 'pelitesti osoittaa arsyttavaksi.',
        'LIVIAN KEHYSMALLI CHATISSA (omistaja 28.8.2026 ilta): kun '
          + 'aiheesta kysytaan ENSIMMAISTA kertaa - tai pelaaja '
          + 'puhuttelee suoraan ("pulu, tiedatko mika on Vesuvius") - '
          + 'vastaus on KEHYSTETTY: alkuun Livian oma puhekielinen '
          + 'alustus, sitten varsinainen vastaus TAYSIN KIRJAKIELELLA '
          + 'ikaan kuin viisas pollo vastaisi (Livia keraa itsensa, '
          + 'fokus palaa ja homma hoituu loppuun asti hyvin), ja '
          + 'loppuun pieni kommentti taas omalla aanella ("olipas '
          + 'pitka sepustus", "onpas ollut hurjaa aikaa"). '
          + 'AUTOMAATTISET JATKOKYSYMYKSET samasta aiheesta: vastaus '
          + 'KOKONAAN pollon aanella, ilman kehysta. UUSI AIHE eri '
          + 'kohdassa: kehys palaa. Nain tieto pysyy selkeana ja Livia '
          + 'elavana ilman etta kumpikaan syo toista.',
        'LIVIA AIKASIIRTYMAN VALITTAJANA - PARIPERIAATE (omistaja '
          + '28.8.2026 ilta): Livian reaktio isoisan merkintaan '
          + 'suunnitellaan aina PARINA - ensin luetaan minkalainen '
          + 'isoisan kertomus on, sitten valitaan miten Livian kannattaa '
          + 'siihen reagoida. Useampia erityyppisia keinoja '
          + 'erityyppisiin teksteihin: HURJA tai synkka tarina (esim. '
          + 'Sofian hirttokertomus) -> Livia EI naljaile isoisalle vaan '
          + 'toimii VALITTAJANA aikasiirtyman kohdalla: avaa '
          + 'historiakontekstia (tama tapahtui jo 150 vuotta sitten, '
