          + '7 kaupunkia kerrallaan.',
        'KAHDEKSAN PAAKATEGORIAA (omistaja 29.8.2026 ilta: "14 on '
          + 'liikaa listaan joka aukeaa kartalle. Noita kategorioita '
          + 'voisi yhdistella"): selitevalikko ja kohdemalli kayttavat '
          + 'KAHDEKSAA paakategoriaa: Kaupungit (portti), Nahtavyydet '
          + '(silma), Kadonneet ihmeet (tahti), Luonto (lehva - myos '
          + 'vuoret, meret ja joet), Elaimet (pollo), Historia ja '
          + 'tarinat (pylvas <- historia+sana+huuto), Kulttuuri ja '
          + 'ruoka (lyyra <- kulttuuri+ruoka+urheilu), Kauppa ja '
          + 'tekniikka (vaaka <- kauppa+tekniikka+merenkulku). '
