          + 'lahtein. Eurooppa ensin, muut mantereet perassa.',
        'YHTENAINEN KOHDEMALLI - TAKYMEKANIIKASTA LUOVUTAAN (omistaja '
          + '29.8.2026 ilta, sanatarkka: "Luovutaan tuosta taky jutusta '
