          + 'elaintakyt ja syvennystarinat YHDISTETAAN yhdeksi '
          + 'lajiksi: KOHDE. Kaikki ovat karttapisteita joista aukeaa '
          + 'sama yhtenainen kortti; erot ovat DATAA: sisallon laajuus '
          + '(pieni fakta / tarina+kuva / tarina+visa), palkkio ja '
          + 'AIHESYMBOLI. Tuikkiva piste ja yksi kerrallaan '
          + '-nostopooli POISTUVAT - loytaminen tapahtuu selitevalikon '
          + 'aihevaloilla, jotka pelaaja itse sytyttaa. Mahdollinen '
          + 'myohempi kevyt lisa: Livia vinkkaa satunnaisesti '
          + 'sisallosta (ei mekaniikkaa, vain repliikki). Toteutus: '
          + 'syvennystarinaera laajenee yhtenaistamiseraksi '
          + '(nostopoolin purku + korttien visuaalinen yhtenaistys '
          + 'samassa). ENSISIJAISUUS (Fable 30.8.2026): tama kirjaus '
          + 'kumoaa KAIKKI aiemmat takykupla-, takyannostelu- ja '
          + 'tuikintamekaniikan kirjaukset (mm. TAKYKUPLA, '
          + 'TAKYANNOSTELU, TAKYNOSTO ON TUIKKIVA PISTE) - ne jaavat '
          + 'Raamattuun historiaksi. Toteutettu v1348.',
        'SKANDAALINOSTON LOOPPITAITTO (omistaja 3.9.2026, sanatarkka: '
          + '"Saisiko nama skandaalinostot taitettua enemman lehden '
          + 'muotoon, missa olisi paaotsikko isolla ja sitten olisi viela '
