          + '(#f6ecc6). Datassa `taitto: \'lehti\'`, `ingressi`, '
          + '`paivays` (js/fokusnosto.js, css/fokusnosto.css osio 9). '
          + 'PILOTTI: GRC sofia-korut (v1480). Kuvaputkelta tilataan '
          + 'jokaiseen looppiin TAYDENTAVA KUVA alkuperaisen rinnalle '
          + '(kohtaus, jota valokuva ei nayta). Monistus kaikkiin '
          + 'skandaalinostoihin vasta omistajan hyvaksyttya pilotin. '
          + 'OMISTAJA 3.9.2026 pilotista: "tee nostosta vahan leveampi, '
          + 'muuten hyva" - kortti 32 -> 40 rem (v1482). HYVAKSYTTY JA '
          + 'MONISTETAAN (omistaja 3.9.2026: "looppi lisalehti on nyt '
