          + 'karttaruudun kulmaan (v1485).',
        'SKANDAALIN MERKKI ON SALAMA (omistaja 3.9.2026 kortilla, '
          + 'kahdeksan luonnoksen katseluarkilta: "en ole taysin '
          + 'tyytyvainen skandaalin symboliin. mieti sille jokin parempi '
