        'SYVENNYSTARINAT KARTALLE (omistaja 29.8.2026 ilta, "Sopii"): '
          + 'v1326:ssa reitittomiksi jaaneet fokusvirtatakyt - '
          + 'syvennystarinat kuvineen ja 50 punnan minivisoineen 12 '
