          + 'valintavaiheet saa purkaa kun merkkireitti on tuotannossa. '
          + 'Jarjestys: elaintakyera -> selitevalikko -> tama.',
        'MERKKIKERROKSEN RASTEROINTI ELEEN AJAKSI (omistaja 29.8.2026 '
          + 'ilta, sanatarkka toive: "Kaikki kohteet saisi siirtya '
