          + 'panoroinnin maan ymparille. Tuotanto: pyramidi '
          + 'generoidaan nykyisella piirtoputkella ja patinalla '
          + 'zoomtasoittain, sailytys R2:ssa, pohjat sailyvat jotta '
          + 'resepti on uudelleenajettavissa. Siirtyma vaiheittain: '
          + 'pilotti + mittaukset ensin, vanha lehtijarjestelma '
          + 'puretaan vasta kun pyramidi kattaa kaikki kaytot. Tama '
          + 'kumoaa v1346:n valiaikaisen jattilaislehtivaiston ja '
          + 'koko lehtivalintamekaniikan paamaarana.',
        'PYRAMIDIN LUKITUT MITAT (omistaja 30.8.2026, kysymyskortit ja '
          + 'suora paatos): syvin taso 7,2 px maailmanyksikkoa kohti = '
