          + 'ajetaan uudestaan, js/media.js FOKUS_VUOSIKERTA on '
          + 'nostettava.',
        'PAPERIVAKIOT JA KARTTAVAKIOT (omistaja 30.8.2026 hyvaksyi '
          + 'tayden patinareseptin; pilotti loysi ettei se toimi '
          + 'laattamittakaavassa): patinan passit jakautuvat kahteen '
