          + 'reunatummennus piirtaisi ruudukon; sama koskee '
          + 'IKAANTYMISEN reunapainoa, joka on nollattu 29.8.). '
          + 'Vinjetointi kuuluu pelitilakerrokseen, jossa se on '
          + 'ruutuavaruudessa yksi koko nakyman yli.',
        'KARTTANOSTOT POLTETAAN LAATTOIHIN (omistaja 31.8.2026, '
          + 'sanatarkka: "mikaan karttanostoista ei kuulu kadota '
          + 'laudalta missaan vaiheessa pelia, joten ne voidaan aivan '
