        'PISTE VAIN NIMEN KANSSA (omistaja 31.8.2026, sanatarkka: '
          + '"Pelkkia pisteita ei saa nakya. Pisteet voivat nakya '
          + 'sitten kun kaupungin nimikin nakyy"): kaupungin merkki on '
          + 'sen nimen ANKKURI eika itsenainen merkinta, joten se '
          + 'piirtyy tasan silloin kun nimi piirtyy. LAAJENTAA '
          + 'vaienneen nimion saantoa (v1385) laattapyramidin '
          + 'nimikerrokseen: kartalla ei ole merkkia ilman nimea, ei '
          + 'kohdemerkkia eika kaupunkipistetta. TAMA EI OLE '
