          + 'toinen puoli viasta (piste syttyi kaksi kynnysta '
          + 'aikaisemmin kuin nimi: isoPiste 0,11 vs. isoNimi 0,22 ja '
          + 'kaupunkiPiste 0,22 vs. nimi 0,45), mutta toinen puoli oli '
