          + 'KOHDALLA (omistaja 3.9.2026 kortilla: "vain laatan paalla olevat '
          + 'pois ja lahella olevat siirretaan sen verran irralleen '
          + 'kaupungista etta ne mahtuvat kartalle eika kayteta siirtoviivaa '
          + '(ei haittaa vaikka ei ole taysin tarkka sijainti). ala kayta '
          + 'tiimalasia vaan pistetta"): kaupungin laatan paalle osuva hetki '
          + '(Lissabon 1484, Fram 1893) EI ole paakartalla - sivu on '
          + 'kaupunkilehdessa ja piste sen kohdekartalla (juttu sanatarkasti '
          + 'hetken teksti); kaupungin lahelle osuva hetki (Santa Fe 1492, '
          + 'Restelo 1497) siirretaan DATASSA vahintaan 9 yksikon paahan '
          + 'kaupungista, jotta se mahtuu kartalle omalla paikallaan ilman '
          + 'kattoVapaa-lippua ja ilman siirtoviivaa. Hetkea ei ladota '
          + 'kaupungin viereen. Kartalla hetki on PISTE kuten muutkin '
          + 'nostot (v1453:n tiimalasi elaa vain kortin ylarivilla). '
          + 'Pilotti 2.9.2026: 10 hetkea, 2 '
          + 'kartalla (Plymouth 1768, Southampton 1912), Ecuador sai '
          + 'ensimmaisen maalehtisivunsa (Darwin). "Kartalla on vain '
          + 'selitevalikon symbolit" pysyy - riveja on nyt yhdeksan.',
        'KAIKKI GENEROIDUT KUVAT MAHDOLLISIMMAN VALOKUVAMAISIA (omistaja '
          + '2.9.2026 ilta: kuvaputki ohjeistettiin uudelleen ja tekee '
          + 'kaikki kuvat uudestaan, "kun aiemmat nayttivat hieman '
          + 'piirroksilta"): jokainen kuvaputken generoima kuva - '
          + 'kohtaamiset, historian hetket, ennen/nyt, karttanostot, '
          + 'elaintayt, aarteet, ihmeet, kansikuvat, kuvituskuvat - '
          + 'tehdaan fotorealistiseksi valokuvaksi, ei piirrokseksi eika '
          + 'maalaukseksi. Poikkeus vain miniatyyrit (yksivariset '
          + 'karikatyyripiirrokset kohdekartalle). Piirrosmainen tulos on '
          + 'hylkaysperuste arviointisivustolla. Kuvat myohastyvat taman '
          + 'uusinnan vuoksi; Fable ei tilaa uusia ennen kuin uusinta on '
          + 'arvioinnissa.',
        'KUVAPUTKEN KUVATYYPIT (omistaja 2.9.2026): kuvajonon '
          + 'tarkastussivustolla jokainen kuvatyyppi on oma kategoriansa, '
          + 'ja omistaja hyvaksyy kuvat AINA ensin sivustolla tai pyytaa '
          + 'uudelleengenerointia - peliin vasta sen jalkeen. Fable saa '
          + 'ohjeistaa uusia kategorioita ja nimeaa kategorian jokaisen '
          + 'kuvatilauksen otsikossa. Kategoriat 2.9.: Kohtaamiset, '
          + 'Historian hetket (lahi | kauko), Ennen/nyt (ennen | nyt), '
          + 'Karttanostot (skandaalit, takynostot, syvennykset), '
          + 'Elaintayt, Miniatyyrit (kohdekartan seepiapiirrokset), '
          + 'Loistoaika / Matkakirjan ihme, Lehtien kansikuvat, '
          + 'Kuvituskuvat (kaikki muu). Kuvatilaukset ja kuittaukset '
          + 'kulkevat postilaatikon kautta (posti/fable-vanha.md <-> '
          + 'posti/kuvatoimitus.md), R2-polku kohtaamiset/<kategoria>/. '
          + 'KUVAPUTKEN PYSYVA TOIMINTATAPA (omistaja 2.9.2026, kuvaputken '
          + 'kuittaus 14:02 UTC): jokainen tilaus menee ensin YKSITYISEEN '
          + 'arviointiin; pelin R2:een vasta omistajan hyvaksynnan jalkeen '
          + '(sivustolla tai chatissa); hylattya tai odottavaa kuvaa ei '
          + 'vieda peliin. Kuvaputken osuus paattyy R2-vientiin ja '
          + 'postikuittaukseen (tunnus, polku, mitat, aikalaiskuvalista); '
          + 'pelin koodi- ja dataviitteet paivittaa FABLE julkaisuketjun '
          + 'kautta, ei kuvaputki. EI KUVIA REPOON (omistaja 2.9.2026 '
          + 'kortilla: "R2-ampariin, JPG-muodossa"): jokainen uusi kuva '
          + 'menee VAIN R2:een ja JPG/sRGB-muodossa sellaisenaan kuin '
          + 'kuvaputki sen toimittaa - ei WebP-muunnosta, ei kopiota '
          + 'assets/-kansioon (miniatyyritkin kohtaamiset/miniatyyrit/ '
          + '512 px JPG). Vanhat assets-kuvat siirretaan ampariin erissa '
          + 'ja poistetaan reposta; repon historian siivous on oma tyonsa. '
          + 'Syy: repo paisui 649 Mt:iin, jokainen kuva kulki gitin ja '
          + 'PR:n kautta ja peilaus toisti sen; R2 on julkinen ja CORS '
          + 'kunnossa, service worker valimuistittaa sen samoin. '
          + 'KUVAMUOTO ON JPG (omistaja 2.9.2026: "kirjaa tama selkeasti '
          + 'raamattuun, etta kaytetaan vain JPG-muotoa"): kaikki pelin '
          + 'kuvat - kortit, lehdet, elaintayt, aarteet, miniatyyrit, '
          + 'kohtaamiset, havainnekuvat - ovat JPG/sRGB sellaisenaan kuin '
          + 'kuvaputki ne toimittaa; ei WebP-muunnosta, ei PNG:ta '
          + '(paitsi liput JA KOHDEKARTAN MINIATYYRIT, joissa on '
          + 'lapinakyvyys: miniatyyri on syvatty piirros paperin paalla, '
          + 'ja JPG:ssa ei ole alfakanavaa - omistajan havainto 2.9.2026 '
          + 'ilta "Kuvaputken tekemia uusia kuvia ei ole syvatty": M1:n '
          + 'JPG-miniatyyrit nakyivat beigeina laatikkoina. Miniatyyrit '
          + 'toimitetaan PNG-muodossa alfakanavalla, 1024 x 1024, '
          + 'syvattyina kuten vanhat WebP-miniatyyrit; peli ei kayta '
          + 'JPG-miniatyyria piirroksena vaan nayttaa taplan, kunnes '
          + 'PNG on amparissa). AINOA MUU POIKKEUS on '
          + 'laattapyramidi (pohja, nostot, viivat), joka pysyy WebP:na, '
          + 'koska tuhansissa jatkuvasti ladattavissa laatoissa 25-35 % '
          + 'pienempi koko ratkaisee. Perustelu: WebP:n edut (koko, '
          + 'alfakanava) eivat merkitse yksittaisissa kuvissa, ja JPG:n '
          + 'laatu ja variprofiili ovat omistajan hallinnassa jo '
          + 'generointivaiheessa. Vanhat webp-assetit jaavat, kunnes ne '
          + 'korvataan uusilla JPG-kuvilla. '
          + 'KOHTAAMISKUVIEN TILAUSJARJESTYS (omistaja 2.9.2026 ilta: "Ala '
          + 'pyyda enempaa kohtaamiskuvia ennen kuin olet saanut ne 16 '
          + 'joista puhuin"): docs/kuvatuotanto-kohtaamiset.md:n taulukon '
          + '16 kuvaa (12 tyylikoetta + Dublin, Praha, Berliini, Rooma) '
          + 'toimitetaan sellaisinaan omistajan arviointiin ennen yhtaan '
          + 'uutta kohtaamiskuvatilausta tai uusintaa. Fable ei tilaa '
          + 'lisaa kohtaamiskuvia eika hyvaksy uusintoja, ennen kuin nuo '
          + '16 ovat perilla. Vanhat kuvat eivat vanhene uuden briefin '
          + 'takia: omistaja paattaa sivustolla, mika kelpaa.',
        'NOSTOJEN SIIRTOVIIVAT (omistaja 1.9.2026 ilta: "otetaan '
          + 'siirtoviivat takaisin karttanostoille (esim. ateena)", v1432; '
          + '2.9.2026: "Lisaa siirto viivat, ne ei viela nay", v1438): '
          + 'jokaisesta sarakkeeseen siirretysta nostomerkista katkoviiva '
          + 'merkin reunasta ankkuripisteeseen, sama jana elavassa '
          + 'kerroksessa ja nostotasolla (js/fokusniput.js '
          + 'nippuViivanJana on yksi lahde). Mitat: leveys 1,6 px, '
          + 'himmeys 0,7, katko 3 / vali 2 (v1438) -> OHENNETTU 2.9.2026 '
          + 'aamulla ("Siirto viivat aivan liian paksuja"): leveys 0,9 '
          + 'px, himmeys 0,55, katko 2,5 / vali 2,5 (v1445; testi '
          + 'vartioi 0,85-1,0 x S), merkin oma muste #3a2819; '
          + 'kynnys yksi katko (3 px), jotta sarakkeesta ei karsiudu '
          + 'ketaan. Periaate: viiva on merkin jatke, ei kartan '
          + 'apuviivastoa. Ladontasaanto v6 - vanhat nostolaatat '
          + 'hylataan kunnes nostotaso on poltettu uudestaan. RUUTUKATTO '
          + 'KOSKEE KOKO NOSTON PIIRROSTA (omistaja 2.9.2026: "symbolit '
          + 'heittelee muodoiltaa ja teksteja puuttuu" / "nyt meni todella '
          + 'oudoksi"): syvassa zoomissa merkki, nimio, sarakesiirtyma ja '
          + 'siirtoviiva kerrotaan SAMALLA suhteella ankkurin ympari '
          + '(nostoladontaKattoSuhde) - ennen katto leikkasi vain merkin, '
          + 'ja viiva, rako ja siirtyma kasvoivat karttavakiona yli '
          + 'viisinkertaisiksi. Ladonta (tiiviste, poltto) pysyy '
          + 'tasoriippumattomana; saanto v7 (v1442). KARTAN OMILLA '
          + 'MAASTOMERKEILLA on sama kasvukatto kuin kaupunkilaatalla, '
          + 'vuorikolmio piirtyy vain nimensa kanssa, ja lehteen '
          + 'poltetun nimen vaiennus poistui (lehtia ei ole) - 27 '
          + 'kaupunkimerkkia sai nimensa takaisin. Avoin: kaupungin nimio '
          + 'voi jaada nappulan alle (oma era, nappulan ruutulaatikko '
          + 'ladonnan varaukseksi).',
        'REITIT LAUTAPELITYYLIIN (omistaja 1.9.2026, kaappaukset: '
          + '"Katkoviivat saisi olla harvempia ja vahan paksumpia... '
          + 'enemman sopon lautapelin oloisia kuin teknisia '
          + 'piirustuksia"; LOPULLISET MITAT hyvaksytty vedoksesta '
          + '1.9.2026): REITTITYYLI viiva 9, jakso 190, katkon osuus '
          + '0,30, helmi 10, keha 6 - MEREN KATKO KAVENNETTU JA TIHENNETTY '
          + '(omistaja 1.9.2026 ilta: "kavenna hieman meren '
          + 'noppareittiviivoja ja tee niista vahan tiheammat"): viiva '
          + '7,5, jakso 150, osuus 0,30 ennallaan, helmet askelmillaan '
          + '(v1431); TIHENNETTY UUDESTAAN (omistaja 2.9.2026: "tihenna '
          + 'laivareitin viivoitus (lyhyempi viiva mutta tiheammassa)"): '
          + 'jakso 90, osuus 0,35 (katko 32 R, vali 58 R), ULOTTUMA.helmi '
          + '58,5 (v1438). PYSYVA SAANTO: katkon on pysyttava yli '
          + '1,5-kertaisena helmen leveyteen, muuten katko muuttuu '
          + 'pisaraksi (testi vartioi); pyoreat paat, deterministinen '
          + 'kasivarahuojunta (siemen reitista - poltto pysyy puhtaana '
          + 'funktiona). MAANTIE PALASI YHTENAISEEN VETOON (omistaja '
          + '1.9.2026 ilta, kumoaa maan osalta katkoviivalinjan; '
          + 'hyvaksynta vedoksista "Hyvaksy + lammita maantieta"): '
          + 'katkoviiva on MEREN ja LENNON merkki, maantie on ohut '
          + 'himmea yhtenainen veto (maaViiva 6, alfa 0,17) ja sen '
          + 'savy on terrakotan suuntaan (152,92,44), jotta se '
          + 'erottuu valtionrajan viileasta musteesta (96,74,46). '
          + 'Maareitin helmea ei ankkuroida - yhtenaisella viivalla '
          + 'ei ole katkoa; paperinvarinen taytto puhkaisee viivan. '
          + 'Merireitin askelhelmi ankkuroituu katkon keskelle ja se '
          + 'katko jaa piirtamatta - viiva ei koskaan osu helmeen. '
          + 'RINNAKKAISET MERIREITIT yhdistetaan osuusyhdistamisella: '
          + 'sama ura piirretaan kerran ja haarat liittyvat siihen '
          + 'liittymasilloilla (~90 % rinnakkaismusteesta pois; '
          + 'uraVahin 200, liitosVahin 150 ja haarasuulle 100, '
          + 'astevartija; pelimoottorin reittidataa ei kosketa). '
          + 'Askelhelmi karsitulta osuudelta jaa pois - helmi ilman '
          + 'viivaa olisi merkki tyhjassa meressa; peli kavelee silti '
          + 'kaikki askelmat. LENTOREITIT EIVAT OLE VIIVATASOSSA (omistaja: '
          + '"Piirretaan ne nakyviin reaaliajassa vasta sitten jos '
          + 'pelaaja paattaa menna lentokoneella") - elava kaari '
          + 'ilmestyy lentovalinnassa ja poistuu perilla. REITIT VAIN '
          + 'LAHITASOILLA (omistaja: 1000 km -nakymasta ulospain '
          + 'piiloon): reittipassi vain z5-z7; rajat ja piirit kaikilla '
          + 'tasoilla; polttopaatos, ei haivytysta. KALUSTEET (kartussi, '
          + 'painajanrivi, kulmakoristeet) nakyvat z0-z3 - toiseksi '
          + 'laajin taso mukaan (omistaja: "nuo tekstit jotka nakyy '
          + 'valkoisen marginaalin paalla"); MERTEN NIMET JA '
          + 'KOMPASSIRUUSU MYOS z3:LLA (omistaja 1.9.2026 ilta: "toiseksi '
          + 'uloin zoomtaso saisi sisaltaa samat lisamerkinnat karttaan '
          + 'kuin uloin taso"; KALUSTEIDEN_YLARAJA 0,3 -> 0,5 piirrossa ja '
          + 'karsinnassa, v1431). ERIKOISPIIRIT POIS (omistaja 1.9.2026 '
          + 'ilta: "Poista pituus ja leveyspiirit nakyvista"): viivataso '
          + 'poltetaan --eipiirit-lipulla (v1429-v1430, luettelo '
          + 'viivataso.piirit=false); reunojen asteviivaimet jaavat.',
        'PYRAMIDIAJOT ILMAN ERILLISTA LUPAA (omistaja 1.9.2026: '
          + '"saat jatkossa ajaa nuo ilman erillista lupaa"): Fable '
          + 'kaynnistaa pohja-, nosto-, viiva- ja paikkausajot oman '
          + 'harkintansa mukaan osana julkaisua ja todentaa tuloksen '
          + 'silmalla. Kysymyskortit jaavat sisalto- ja '
          + 'tyylivalintoihin.',
        'MAATUMMENNUS LAHIZOOMILLA (omistaja 31.8.2026 ilta, '
          + 'sanatarkka: "ymparoivat valtiot voisi tummentaa hieman '
          + 'reaaliajassa ja maan aariviivat piirtaa hieman '
          + 'paksummalla. nama voisivat havita valittomasti siirron '
          + 'alkaessa ja tulla feidaten sisaan"; tarkennus samana '
          + 'iltana: efekti paalla KOKO pelaajan normaalilla '
          + 'zoomialueella uloin sallittu zoomi mukaan lukien, pois '
          + 'vain kun kehittajatilassa zoomataan sita kauemmas): '
          + 'pelitilakerros - tumma kalvo (kartan muste) MUIDEN MAIDEN '
          + 'polygoneihin, MERI JAA KOSKEMATTA (omistaja 31.8.2026 yo: '
          + '"Merta ei tarvitse tummentaa" - alkuperainen koko arkin '
          + 'evenodd-kalvo tummensi merenkin), '
          + 'paalle maan aariviiva ~1,5x rantaviivan vahvuudella. '
          + 'PYSYY NAKYVISSA PANOROINNISSA (omistaja 1.9.2026 aamu: '
          + '"Kartan tummennus voisi pysya panoroitaessa paalla"; '
          + 'mitattu kohinan sisaan), piiloutuu vain zoomieleessa '
          + 'ja palaa feidaten levossa; ei per-frame-tyota. Maapolygonit '
          + 'laiskana datana (NE 50m, laudan projektiossa) - ei '
          + 'buildiin. BLUR JAA KOKEILUVARAUKSEKSI (omistaja: "en ole '
          + 'varma onko se edes tarpeellista, tummennus voi riittaa") '
          + '- CSS-luokkakoukku on, toteutusta ei.',
        'NOSTON RUUTUKATTO (omistaja 1.9.2026 aamu, sanatarkka: '
          + '"Karttanostot ovat aivan liian isolla. Tee max sama koko '
          + 'kuin kohdekaupungin koko"): noston merkki+nimio ei '
          + 'ruudulla koskaan kohdekaupungin merkkia+nimea isompi. '
          + 'Nosto on yha karttavakio (NOSTOLADONTA_S), mutta kasvu '
          + 'katkaistaan kaupunginnimen mittaan (syva zoomi 2,4x -> '
          + '1,0x; keskizoomi 1,19x -> 1,00x; kaukozoomit ennallaan). '
          + 'YKSI KAAVA pelille ja generaattorille; ladonta ja '
          + 'osumasade laskevat kattamattomalla mitalla, joten '
          + 'poltettu ladonta pysyy tasoriippumattomana ja sormen '
          + 'osuma-ala sailyy. POLTTO OLETTAA DPR 2:N - tasmallinen '
          + 'takuu tulee vain elavasta kerroksesta; jos katto halutaan '
          + 'joka laitteella tasmalleen, nimio siirretaan '
          + 'ruutukerrokseen kuten paikannimet (avoin jatkokysymys). '
          + 'PIIRTOSAANTOTUNNUS: ladontasaannon versio (saanto) on '
          + 'tiivisteen syote ja luettelon kentta - vanhalla saannolla '
          + 'poltettu nostotaso PIILOTETAAN kokonaan uusintapolttoon '
          + 'asti, ettei vanha iso muste jaa elavan merkin alle.',
        'NIMIOLLE NELJA KYLKEA (omistaja 1.9.2026 aamu, kuvakaappaus: '
          + '"KarttaNostoista puuttuu teksteja" - BGR): jokainen '
          + 'nimellinen nosto saa nimion; pudotus sallitaan vain '
          + 'todelliseen tormaykseen. Vaisto tunsi vain oikean ja '
          + 'vasemman kyljen, joten vaakarivi tukki molemmat vaikka '
          + 'ylla ja alla oli tyhjaa - nyt nelja kylkea yhdesta '
          + 'asemointikaavasta (vaisto, poltto, musteen laatikko ja '
          + 'rasteri lukevat samaa). Mitattu koko maailma: pudonneet '
          + '55 -> 40 nimellisesta 605:sta; pudotuksen syy '
          + 'instrumentoitu (tools/savukkeet/mittaa-nostonimiot.mjs). '
          + 'EI-BUGIT KIRJATTU: kaupungin nimi tulee '
          + 'kaupunkikerroksesta ja poltetun maastonimen paalle ei '
          + 'ladota kaksoisnimea (nimiJoKartalla).',
        'NOSTON TEKSTI ON KOKONAAN NAPAUTETTAVA (omistaja 1.9.2026 '
          + 'ilta: "Saisiko karttanostoissa myos tekstit '
          + 'kokonaisuudessa klikattaviksi? Nyt vain osa tekstista on '
          + 'klikattavissa"): nimion koko ala avaa kohteen kortin '
          + 'siina missa merkin 44 px ympyrakin. Kolme lahdetta, sama '
          + 'lopputulos - laattaan poltettu ja rasteroitu nimio saavat '
          + 'nakymattoman suorakaiteen vaiston valitsemaan kehykseen '
          + '(kilpailee napautuksesta keskipisteella kuten muutkin '
          + 'osumamuodot), nimikerroksen latoma elava nimi ottaa '
          + 'napautuksen itse (data-kohde). Kumoaa aiemman "nimio ei '
          + 'ota napautuksia" -linjan; napautusalueet eivat muuta '
          + 'ladontaa eivatka polttoa.',
        'PAAKAUPUNKI AIKAKAUDEN TAPAAN (omistaja 31.8.2026 ilta: '
          + '"miten tuon ajan kartoissa eroteltiin paakaupungit ja '
          + 'muut kaupungit? tassa voisi kayttaa samaa '
          + 'visualisointia"): 1800-luvun atlaskonventio on '
          + 'kaksoisrengas (piste renkaan sisalla) + nimi harvennetuin '
