          + 'kaupungit ennallaan. Rengas ja typografia valitaan SAMALLA '
          + 'ehdolla, etteivat ne eriydy.',
        'KAUPUNKILAATAN KASVUKATTO (omistaja 31.8.2026 ilta, '
          + 'kuvakaappaus: "kaupunkilaatat nakyvat jostain syysta '
          + 'aivan hervottoman isoina"): laatta on karttavakio '
