          + 'Kosketusalueet (44/48 px) eivat kutistu; nappula seuraa '
          + 'laattaa (v1393:n sidonta).',
        'IKILUMI 5500 METRIIN JA JARVILLE VESISAVY (omistaja '
          + 'kysymyskortilla 31.8.2026 ilta, vertailukuvista; TARKENTAA '
          + '30.8. korkeusasteikkokirjausta): lumiporras 7000 m tayttyi '
          + 'NELJASSA solussa koko maapallolla (3 kaariminuutin ruudukko '
