          + 'tavullakaan (todennettu pikselitasolla). Voimaan '
          + 'seuraavassa pohja-ajossa (v1397).',
        'NIPISTYS EI ENAA NAPSAHDA PORTAIKKOON (omistaja 30.8.2026, '
          + 'kysymyskortti, sanatarkka havainto: "Zoomatessa kartta '
          + 'hypahtaa hieman eri syvyydelle kun sormet irroittaa ja '
          + 'uusi karttataso piirtyy"): ele paattyy siihen '
          + 'mittakaavaan, mihin sormet jaivat. KUMOAA kohdan '
          + '"NIPISTYS PAATTYY AINA PORTAIKON TASOON". Perustelu sille '
          + 'ei ollut eleen vaan RASTEROINNIN ehto - "mittakaavoja on '
          + 'kourallinen ja sama taso palaa uudestaan, jolloin '
          + 'valimuistit osuvat" - ja pyramidissa ei ole mitaan '
          + 'rasteroitavaa: valitseTaso poimii lahimman kahdeksasta '
          + 'laattatasosta MILLE TAHANSA vapaalle kertoimelle ja selain '
          + 'skaalaa laattaa korkeintaan neliojuuri kaksi. Valimuisti '
          + 'osuu siis tasoon eika kameran kertoimeen. Napsautus '
          + 'sen sijaan MAKSOI: portaikon askel on 1,5, joten '
          + 'pahimmillaan ele siirsi nakymaa viela 22 % sen jalkeen kun '
          + 'sormet olivat irronneet. PAINIKKEET PITAVAT PORTAIKKONSA, '
          + 'eika se vaatinut uutta koodia: zoomaaPainikkeella osasi jo '
          + 'jatkaa portaiden valista lahimpaan portaaseen '
