          + 'arkki kahdessa laatassa, joten valiin mahtuu tasan seitseman '
          + 'tuplausta.',
        'MEREN SYVYYSPORRASTUS KAKSINKERTAISTETAAN (omistaja '
          + '30.8.2026, kysymyskortti, valinta "vahvempi savyporrastus"): '
          + 'omistajan TestFlight-kysymys oli "miksi meressa ei nay '
          + 'syvyysmerkkeja", ja mitattu vastaus oli ettei niita nay '
          + 'koska niita EI OLE - koko asteikko 0...-5000 m kulki 42 '
          + 'savya, kun paperin ja musteen vali on noin 250. '
          + 'Vaihtoehdoista (syvyyskayrat, luotausluvut, vahvempi '
          + 'porrastus) valittiin porrastus: ei yhtaan uutta viivaa '
          + 'eika tavua, vain se signaali nakyviin joka aineistossa jo '
          + 'on. MITATTU: kontrasti 42 -> 88 savya (2,10x) ja pahin '
          + 'gradientin taite 1,7 -> 3,4 savya / 1000 m, eli yha alle '
          + 'puolet siita 6,9:sta joka aiheutti 29.8. bandingvalituksen '
          + '- monotoninen kuutiokayra loi sen pelivaran, jolla '
          + 'kontrastin voi ottaa takaisin. Matalan meren porras '
          + '(0...-30 m) pidetaan loivimpana, ettei jokaisen rannikon '
          + 'ymparille piirry tumma kaula, ja syvinkin meri pysyy '
          + 'lampimana (134,132,124) eika muutu harmaaksi. '
          + 'KARSINTARAJA SEURAA MUKANA: generoi-laattapyramidin '
          + 'HARVA_RAJA 2 -> 4, koska sama fyysinen tasaisuus tuottaa '
          + 'nyt 2,10x enemman kanavaeroa; ilman sita umpimeren '
          + 'karsinta lakkaisi. Syvyyskayrat ja luotausluvut jaavat '
          + 'edelleen tekematta.',
        'VESIVIIVOITUS POIS KUNNES SE ON OIKEAA DATAA (omistaja '
          + '30.8.2026, sanatarkka: "tuo nykyinen viivoitus onkin '
          + 'pelkka geneerinen ja sen voisi jattaa kokonaan pois siihen '
