          + 'Passi pois paalta. KUMOAA taman kohdan laattapyramidin '
          + 'tyyliohjeesta ("rannikon vesiviivoitus"). Samalla meren '
          + 'oma syvyyssignaali paastetaan esiin: litistys 0,20 -> '
          + '0,70, koska litistyksen ainoa peruste oli LEHTIEN SAUMAT '
          + '(23 lehden otoksessa meren keskisavy vaihteli L=199,9...'
          + '211,2), eika pyramidissa ole saumoja. Banding korjataan '
          + 'rampin muodolla eika datan havittamisella: mitattuna '
          + 'portaiden tihennys 7 -> 17 PAHENSI taitetta 6,9:sta '
          + '12,3 savyyn / 1000 m, koska jokainen silmamaarainen piste '
          + 'tuo oman taitteensa; monotoninen kuutiokayra alkuperaisten '
          + 'seitseman ankkurin lapi antaa 1,84 samalla '
          + 'kokonaiskontrastilla. ETOPO1 on topo-batymetrinen, joten '
          + 'data on jo haussa mukana. Varsinaiset syvyyskayrat '
          + '(marching squares kiinteilla syvyyksilla) ovat myohempi '
          + 'oma eransa.',
        'ERILLISLAUDASTA LUOVUTAAN (omistaja 30.8.2026 aamu, '
          + 'kysymyskortti: "Poista erillislauta kokonaan"): Euroopan '
          + 'erillislauta poistetaan ja MAAILMANKARTTA ON AINOA '
