          + 'epailee / torjuu / huvittuu / hammastyy / vakavoituu), voimakkuus '
          + '0-1, siirtyma ankkurin lopusta (ms) ja perustelu; tarkoituksella '
          + 'hiljaiset osuudet merkitaan. Tavalliseen kohtaan pieni ele, '
          + 'vitsiin nauru, hurjaan asiaan voimakkaampi; ei nyokkaysta ja '
          + 'pudistusta vuorotellen merkityksesta riippumatta. 3) Ajoitus '
          + 'tarkistetaan olemassa olevaa aanitetta vasten sanakohtaisilla '
          + 'aikaleimoilla (ElevenLabs forced alignment, kuten linsseissa) - ei '
          + 'merkkimaarasta arvottuja aikoja eika uutta aanen generointia. '
          + '4) Pilotti Marseille ensin, sitten muut tekstit rajatuissa erissa; '
          + 'sama prioriteetti- ja nyanssiajattelu sovitetaan koko '
          + 'reaktiorekisteriin. 5) Perusilmeet ja pelisynkronointi ensin; '
          + 'asennot (kadet puuhkassa), vaatteet, hatut, rekvisiitta ja '
          + 'harvinaiset paluut (kuumailmapallo, laskuvarjo, vain turvalliseen '
          + 'joutokohtaan) myohemmin. Tyonjako (tarkennettu 11.9.2026 klo 09.30 '
          + 'tekstisession kanssa): sisalto, ajoitusmoottori js/luentareaktiot.js, '
          + 'js/luenta.js-kytkenta, aikaleimatyokalu ja kohdistusajot: Fable; '
          + 'reaction-tapahtuman ele-sovitin ja paluu ylaviistokatseeseen '
          + '(js/livia-*.js): tekstisessio. Tekninen sopimus (tapahtumakentat, '
          + 'luonnollinen loppu, aikaleimojen validointi ja aanisidonta) asuu '
          + 'docs/pulu-reaktiot.md:n osiossa Luentareaktiot.',
        'PUHELIMEN LEHDESSA PULU OIKEAAN REUNAAN; PULU REAGOI ARTIKKELIN CHATISSA '
          + 'JA CHAT LAHEMMAS PULUA (omistaja 11.9.2026 aamu tekstisession kautta, '
          + 'kaksi iPhone-kaappausta Marseillesta): 1) puhelimen (enintaan 600 px) '
          + 'lehdessa suljettu pulu ja sen 48 px nappi ovat oikeassa reunassa '
          + '(noin 80 px oikeammalla kuin ennen); KORVAA 10.9. toiveen 48 px '
          + 'vasemmalle. 2) Pulu reagoi myos nahtavyysikkunassa (artikkelin '
          + 'oma chat) esitettyyn kysymykseen, ja chat-ikkuna avautuu lahemmas '
          + 'pulua. Toteutettu tekstisession v1750-v1751:ssa.',
        'PULU REAGOI MYOS LEHDESSA, LAUKUSSA JA VISASSA; AARRE YKSI ISO ELE; RAHA '
          + 'VAIN PANKKIAPU; PITKA ODOTUS KERRAN (omistaja 11.9.2026 klo 09.30, '
          + 'vastaukset reaktiorekisterin epavarmiin kohtiin): 1) Avoin dialogi ei '
          + 'esta pulun reaktioita, kun dialogi on kaupunki- tai maalehti, '
          + 'matkalaukku tai visa/kohtaamiskortti - pulu nakyy niiden paalla ja '
          + 'saa reagoida; muut dialogit (asetukset, voitto, ilmoitukset) pysyvat '
          + 'hiljaisina. 2) Aarteen loyto on yksi iso ele (ilo 0,8); isoisan '
          + 'aarremerkinnan avautuessa ja luennan aikana pulu vain kuuntelee. '
          + '3) Raha: vain vararikon pankkiapu saa eleen (lammin 0,5); palkkiot '
          + 'kuuluvat aarrejuhlaan, muut raharivit hiljaisia. 4) Chatin pitka '
          + 'odotus (yli 6 s) saa kerran hillityn eleen (hammentynyt 0,3), sitten '
          + 'mietinta jatkuu. Fablen ratkaisut muihin kohtiin: saapumisen kolme '
          + 'rivia sailyvat; aihesivun symboli johdetaan id:sta koodissa; '
          + 'Venetsian photo-tagi vain kartan pakkaan, ei lehteen; pollo.teksti '
          + 'ei piirry, ei rivia; radion sammunut nappi hiljainen.',
        'PULUN REAKTIOREKISTERI: JOKAINEN PELITILANNE KIRJATAAN REAKTIOTA VARTEN '
          + '(omistaja 10.9.2026 klo 23.05 tekstisession kautta, sanatarkasti: '
          + '"Hyva, fable voisi tehda mahdollisimman laajan selvityksen kaikista '
          + 'tilanteista ja kirjoittaa jatkossa tilanteet suoraan ylos reaktioita '
          + 'varten"): 1) docs/pulu-reaktiot.md on versionhallittu, elava '
          + 'reaktiorekisteri: jokainen merkityksellinen pelitilanne (aloitus, '
          + 'saapumiset ja lahdot, matkat, matkakirja ja luenta, lehdet ja kuvat, '
          + 'kortit, chat ja mikrofoni, odotus ja virheet, aarteenetsinta, '
          + 'kohtaamiset ja tarinan tunnetilanteet, laukku, linssit, joutohetki '
          + 'ja tausta) saa rivin: pysyva tilanne-ID, nakyma, tiedosto ja '
          + 'laukaisukohta, alku- ja loppuehto, tunnetagi ja voimakkuus TAI '
          + 'perusteltu "ei reaktiota", ajoitus, prioriteetti ja keskeytys, '
          + 'paluu perustilaan, asusteet ja katse, mobiili- ja modaaliehdot, '
          + 'kytkennan tila (dokumentoitu / merkitty sisaltoon / kytketty / '
          + 'testattu pelissa) ja testipolku. 2) Sisalto ei nimea SVG-eleita '
          + 'vaan semanttisen tunnetagin { tunne, voimakkuus } (utelias, lammin, '
          + 'ilo, hammastys, miettiva, vakava, ylpea, rakkaus, hammentynyt, '
          + 'jannitys; js/livia-tilanteet.js ilmoitaLivianTunne). 3) Pulu seuraa '
          + 'pelia ymmarrettavasti mutta ei elehdi jatkuvasti eika kilpaile '
          + 'tarinan tai puheen kanssa: puhe, luenta, odotus, kortti ja '
          + 'taustaele eivat kaynnista ristiriitaisia reaktioita; vanhentunutta '
          + 'elettä ei jonoteta; hiljennys ja vahennetty liike huomioidaan. '
          + '4) SISALLON VALMISTUMISEN TARKISTUSKOHTA: uusi tai muuttuva kohtaus, '
          + 'kaupunki, linssi tai kayttoliittymatila ei ole valmis ennen kuin '
          + 'sen tilanteet on kirjattu rekisteriin ja tunnetagi merkitty '
          + 'sisaltoon samassa muutoksessa. Tekniset kytkennat (livia-*.js, '
          + 'pollo.js) tekee tekstisessio rekisterin puutelistasta.',
        'IHMISEN MATKA: AFRIKKA 0,7 S SANAN JALKEEN, PULU PIILOSSA KUNNES TEKSTI '
          + 'ON ALHAALLA JA KAVELEE SITTEN OIKEALTA SISAAN, VANOJEN PAAT EIVAT '
          + 'RAPSY (omistaja 10.9.2026 klo 23.00, iPad-kaappaus Arabian jaksosta, '
          + 'sanatarkasti: "Siirra Afrikan ilmestymista puoli sekuntia '
          + 'aiemmaksi. Pulun pitaisi olla piilossa kunnes tekstit siirtyvat '
          + 'alareunaan ja siita parin sekunnin paasta pulu voisi kavella '
          + 'kartalla oikeasta reunasta sisaan. Kuvassa nakyvat ihmis janat '
          + 'rapsivat niiden paissa, saisiko korjattua pois?"): 1) Avauksen '
          + 'zoomi paattyy noin 0,7 s "Afrikasta"-sanan jalkeen (AFRIKAN_VIIVE_MS '
