          + 'pulu (nappi ja kasvot) on kokonaan piilossa, kunnes avausjakson '
          + 'teksti on laskeutunut ruudun alalaitaan; noin kaksi sekuntia sen '
          + 'jalkeen pulu kavelee kartalle ruudun oikeasta reunasta sisaan '
