          + '3) Ihmisen matkan vanat (kulkevat reittikaistat) eivat saa rapsya '
          + 'paistaan: piirron on oltava vakaa sekä paikallaan etta kulkiessa.',
        'KAIKKI EUROOPAN ISOISAN JA PULUN KUVAT PELIIN; TEKSTISESSIO KYTKEE '
          + '(omistaja 10.9.2026 klo 21.10 tekstisession kautta, sanatarkasti: '
          + '"Kaikki isoisan ja pulun kuvat voisi lisata peliin. Ne eivat jostain '
