          + 'hyvaksyntareitti on paattynyt - loput 34 isoisan luentakuvaa (V1.4-'
          + 'masterin retain-kuvat: Amsterdam ja Venetsia paper-v5, muut paper-v4) '
          + 'menevat peliin matkakirja.luentakuva-kenttaan kuvatoimituksen '
          + 'items[]-toimituksesta ilman uusia generointeja; neljä '
          + 'tarinakorjausta sailyvat. Kytkennan ja kuvatekstien lyhennyksen '
