          + 'niin juuri se kuva pitaa tulla nakyviin taysikokoisena. eli riippuen '
          + 'siita mika kuva on pakan paallimmaisena pitaa aueta ensimmaisena '
          + 'karusellissa taydessa koossa"). 3) '
          + 'Matkakirjakortti palaa auki HETI kartan liikkeen paatyttya luennan '
          + 'aikana, ei rauhoitusajan jalkeen (tarkentaa 10.9. klo 10.35 '
          + 'linjausta). 4) Kuvapakan napautukset eivat ole kartan liiketta: '
          + 'kortti ei kutistu, kun pelaaja selaa pakkaa. 5) Luentakuva ja '
          + 'pakka asettuvat selvasti kaupungin laatan ylapuolelle, eivat sen '
          + 'paalle tai kiinni siihen (tarkentaa SAAPUMISESSA KAMERA ASETTUU '
          + '... -linjausta 9.9. klo 16.10).',
        'UUSI ASIA TEHDAAN TARKASTUSKIERROKSINA, KUNNES TEKIJA ON ITSE '
          + 'TYYTYVAINEN (omistaja 10.9.2026 aamu, tekstisession valittamana '
