          + 'SARJATEHTAVA ALOITETAAN AINA PIENELLA KOKEILUERALLA.',
        'MATKAKIRJAKORTTI AUKEAA SAAPUMISESSA JA PALAA AUKI LUENNAN AJAN '
          + 'KARTAN LIIKKEEN JALKEEN (omistaja 10.9.2026 klo 10.35, '
          + 'sanatarkasti: "Matkakirjan teksti saisi aina aueta kun tullaan '
          + 'uuteen paikkaan ja se saisi pysya auki niin kauan kuin puhe kestaa. '
          + 'Jos karttaa liikuttaa niin se katoaa pieneksi mutta puheen aikana '
          + 'se palutuu liikkeen jalkeen. Puheen jalkeen se voi pysya '
          + 'piilossa."): 1) Uuteen kaupunkiin saavuttaessa ylavasen '
          + 'matkakirjakortti avautuu aina kokonaan. 2) Kortti pysyy auki niin '
          + 'kauan kuin kertojan luenta soi. 3) Kartan liikuttaminen (panorointi, '
          + 'zoomi, napautus) kutistaa kortin yhden rivin lapuksi kuten ennen, '
          + 'mutta jos luenta on yha kesken, kortti palaa auki heti liikkeen '
          + 'paatyttya. 4) Luennan paatyttya kutistunut kortti saa jaada '
          + 'lapuksi; napautus avaa sen kuten ennen. Tarkentaa linjausta '
          + 'PAIVAKIRJALLA EI OLE ENAA VALIKOKOA (7.8.2026).',
        'PULUN PIKSELIKASVOT TULOSSA; B-KASVO ON VALIAIKAINEN PELIKOKEILU '
          + '(omistaja 10.9.2026 klo 00.55, sanatarkasti: "uudet pulun '
