          + 'Tallinna (marsipaanipalan leikkaus); muut 41 sailyvat. Giza-tyyli '
          + 'sailyy. Historiallisten kuvien erillinen hyvaksyntareitti ei muutu.',
        'PULU-CAM: RAKKAUSKOHTAUS 3-5 KUVAA, KAKSI KUVATEKSTIA MOLEMMILLE, '
          + 'HAVAINNEKUVA-LINKKI PITKAN LOPUSSA, TARRA YHTENA PNG:NA OMISTAJAN '
          + 'VALINNASTA (omistaja 9.9.2026 klo 18.50 postilaatikon kautta, '
          + 'tekstisession valittamana): 1) Tavallinen kohde saa 1-3 pulun kuvaa, '
          + 'rakkauskohtaus 3-5, jos tarina tarvitsee - pakassa siis enintaan '
          + 'kuusi kuvaa isoisan kuvan kanssa. 2) Seka isoisan etta pulun kuviin '
          + 'kaksi kuvatekstia: lyhyt suoraan kuvan alle, pitka vasta koko ruudun '
          + 'nakymaan; pitka on oma kertova teksti (yleensa 300-600 merkkia), ei '
          + 'luennan lisaosa. 3) Isoisan pitkan kuvatekstin lopussa on aina '
          + 'toimiva Havainnekuva-linkki, joka avaa pelin selityksen '
          + 'havainnekuvista; lyhyessa ei ole linkkia. 4) PuluCam-tarra on yksi '
          + 'erillinen RGBA-PNG (valkoinen pohja piirroksen ja PuluCam-tekstin '
          + 'siluetin sisalla, ulkopuoli lapinakyva); se korvaa selfie-PNG + '
          + 'HTML-teksti -rakenteen. Vaihtoehdot A-F ovat omistajan valintaan; '
          + 'ennen valintaa kuvat nakyvat puhtaina ilman tarraa. 5) Tyonjako: '
          + 'tekstisessio suunnittelee ja promptaa PuluCam-kuvat, kuvatoimitus '
          + 'generoi ja julkaisee arviointiin, Fable kytkee hyvaksytyt.',
        'PULU-CAM: NOIN 14 MM:N LAAJAKULMA JA RAKASTUMISKUVIIN SYDANREUNAT '
          + '(omistaja 9.9.2026 klo 16.39 postilaatikon kautta, tekstisession '
          + 'valittamana): PULU-CAM-kuviin selvasti laajempi, noin 14 mm:n linssin '
          + 'nakokulma - pulun poikkeava katselukorkeus, laheiset kohteet ja tilan '
          + 'syvyys korostuvat. Rakastumiskuviin (Venetsian kolmen kuvan sarja) '
          + 'sydamia ja muita ihastumispiirroksia kuvan reunoille, lisaantyen '
          + 'sarjan edetessa; valokuvan keskusta pysyy uskottavana nykyajan '
