          + 'Livia selittaa vain kun selitys on itse vitsi. Sanasto rajataan '
          + 'kuuteen ydinsanaan (zop, tiplo, K3, yoikkuna, lakkipiste, G.) ja '
          + 'kahteen harvinaiseen (H-reitti, K.V.). 3) Livian kuplan sanat menevat '
          + 'hanen omaan elamaansa: nykypaiva, linnun nakokulma, kuittaus '
          + 'isoisalle, oma sekoilu, rakkaus (Venetsian han) ja persous pullaan. '
          + 'Yksi asia per kupla; yksi kupla per kaupunki paasaantoisesti.',
        'HORATION OMA KIELI: KAHDEKSAN SANAA, JOTKA TOISTUVAT JA JOTKA LIVIA '
