          + 'kokoa - elava ladonta jaa. TARKENNUS 3 (omistaja 18.9.2026 klo '
          + '09.20 Suomen aikaa, sanatarkasti: "Enta topografiakartta? '
          + 'Nayttaa, etta siina ainakin aiemmassa versiossa latautui ensin '
          + 'normaali kartta ja sitten topografiakartta sen paalle. Kuluttaako '
