          + 'kuultamaan, koska viivat ovat oma taso); tumma peite avauksessa '
          + 'jaa vain latauksen ajaksi. Mitataan: avauksessa ensimmainen '
          + 'reliefikehys < 300 ms, seepiapohjan laattoja ei haeta linssin '
          + 'aikana (0 pyyntoa), muisti pienenee vs. nykyinen.',
        'KARTTAUUDISTUKSEN PAATOKSET 35: LUENTAKUVAT PIENEMMIKSI, KUVATEKSTI '
          + 'PAPERILLA, OHITA-TEKSTI, PIKKUKUVAT MATKAKIRJAN LOPPUUN (omistaja '
