          + 'kuvat saisivat tulla vahan pienempina ruudulle. Lisaa valkoista '
          + 'paperia kuvan alareunaa ja lado kuvateksti sen paalle. Pida huoli '
          + 'etta lisapaperi menee hieman kuvan taakse jotta kuvan ja '
          + 'lisapaperin valiin ei jaa vahingossa ohutta lapinakyvaa viivaa. '
