          + 'matkakirjan tekstin lopussa ja ne voisi siella klikata auki '
          + '(pikkukuvat eivat nay kun matkakirja on pienennettyna). Saitko '
          + 'kiinni?"): 1) saapumisluennan isoisan ja pulun kuvat (js/'
          + 'fokusvirta.js luentakuva, css/fokusvirta.css) nakyvat ruudulla '
          + 'PIENEMPINA kuin nyt; 2) kuvan alareunaan jatkuu VALKOINEN PAPERI, '
          + 'jolle kuvateksti ladotaan; paperi alkaa hieman kuvan alta (limitys '
          + 'kuvan taakse), jotta kuvan ja paperin valiin ei jaa lapinakyvaa '
          + 'viivaa; 3) kuvan ja kuvatekstin alle pieni "Ohita"-teksti, joka '
          + 'hyppaa isoisan ja pulun tekstien (luennan) yli ja nayttaa kartan '
          + 'heti; 4) samat kuvat ovat PIKKUKUVINA isoisan matkakirjan '
          + '(saapumismerkinnan) tekstin lopussa ja avautuvat sielta '
          + 'napautuksesta; kun matkakirja on pienennettyna, pikkukuvat eivat '
          + 'nay. Mitataan 390 px: kuvan leveys pienempi kuin nyt (luku '
          + 'kirjataan), paperin ylareuna kuvan alareunan alapuolella '
          + '(limitys > 0 px, ei rakoa), Ohita-teksti nakyy ja vie kartalle '
          + 'alle 1 s:ssa luennan pysahtyessa, pikkukuvat matkakirjan lopussa '
          + 'auki-tilassa ja poissa pienennettyna. TARKENNUS (omistaja 17.9.2026 '
          + 'klo 22.10 Suomen aikaa, kortti): Ohita PYSAYTTAA luennan - aani ja '
          + 'kuvat loppuvat heti, kartta nakyy; isoisan ja pulun tekstit jaavat '
          + 'luettaviksi matkakirjaan, pulun luentareaktiot eivat enaa tule. '
          + 'Tila: TOTEUTETTU (kuva 367 -> 287 px, limitys 13 px, Ohita 2 ms, '
          + 'pikkukuvat 3/3; mittaa-luentakuvat 16/16), JULKAISTU v1934. '
          + 'TARKENNUS 2 (omistaja 18.9.2026 klo 06.55 Suomen aikaa, iPhone-kuva '
          + 'v1935 Pariisin luentakuvasta, sanatarkasti: "Kuvatekstiin ei saa '
          + 'tulla varjoa. Kun painaa Ohita niin myos pulun luenta pitaa '
          + 'loppua"): 5) kuvan varjo (box-shadow) ei saa langeta kuvatekstin '
          + 'paperille - paperi on kuvan takana samassa tasossa, varjo vain '
