          + 'pulun luennan (pulun oma luentasarja, luentareaktiot, mahdollinen '
          + 'myohemmin kaynnistyva pulun aani) - yksi pysaytys, joka kattaa '
          + 'kaikki saapumisen aanet ja kuvat. Mitataan 390 px: kuvatekstin '
          + 'paperin alueella ei varjoa (pikselit paperin variset kuvan '
