          + 'isoksi. Tsekkaa kaikkialta lapi"): kortissa ja lehdessa kuvan alla nakyy '
          + 'VAIN lyhyt kuvateksti; rivit "Matkakirjan havainnekuva - lahdeperusteinen '
          + 'johdannainen" ja "Valokuva: tekija, Wikimedia Commons (CC ...)" siirtyvat '
          + 'SUURENNOKSEEN (kuvan napautus isoksi), jossa ne nakyvat kerran kuvan alla '
          + 'linkkeineen (CC BY / BY-SA -attribuutio tayttyy suurennoksessa). Koskee '
          + 'KAIKKIA pintoja: kartan kohdekortti (fokuskohteet), nostokortti '
