        'KARTTAUUDISTUKSEN PAATOKSET 50: ASTRONAUTIN KAMERAN ZOOMIKATTO HIEMAN LAHEMMAS, '
          + 'JA LAATAT JOTKA EIVAT PIIRRY iOS:LLA (omistaja 19.9.2026 klo 17.45 Suomen aikaa, '
