          + 'piirry. Chromium-lohko 47 on 53/53, eli WebKit/iOS-kohtainen (tekstuurikoko, '
          + 'muisti tai lataus). 3) NOSTOKORTTI: karusellin pystykuva ei keskity (tyhja '
          + 'tumma paneeli oikealla) ja pulu istuu leipatekstin paalla kortin ollessa '
          + 'auki; kortin ylareuna tilapalkin alla. TILA PYSTYKUVA (Opus 1 klo 19.23, '
          + 'mitattu WebKit ja Chromium kosketustilassa): pystykuva OLI oikein (contain, '
          + 'keskella); oikean laidan tumma paneeli oli seuraava-nuolen :hover-tausta, '
          + 'jonka iOS jattaa paalle napautuksen jalkeen (yleinen button:hover css/'
          + 'styles.css voitti nuolen background:none). Korjaus: hover-tausta vain @media '
          + '(hover: hover), kosketukselle lyhyt :active, kuvanuolet ilman taustaa; '
          + 'safe-area-inset-top kortin ylareunaan. Uusi savuke-nostokuva-karuselli 8/8. '
          + 'Julkaistaan v1963. TILA LAATTAVIRHE (Opus 1 -erat '
          + 'webkit-napa ja laastari 19.9.2026 klo 17.50-18.50 Suomen aikaa, mitattu): '
          + 'EI WebKitin vika. Juurisyy 1: reliefipyramidin alinaytteistetyissa laatoissa '
          + 'meri on tasaista MERIVARIa (z5-z7, tuhansia merilaattoja polttamatta), ja '
          + 'Astronautin kameran laastari piirsi ne 4k-batymetrian paalle - Chromium-'
          + 'lohko 47 ei nahnyt, koska laastari syttyy kankaan px-korkeudesta ja iPhone '
          + 'dpr 3 sytyttaa sen korkeammalla. Korjaus (pallolaatat.js, vain '
          + 'astronauttitila): merivari +-6 ja 2 px reunalaajennus -> alfa 0, merilaatalle '
          + 'ei taustatayttoa, materiaali alphaTest + esikerrottu alfa, leveysraja +-60 '
          + '(Gronlanti ja napa jaavat 4k-pohjalle); Kreetan koeala 27,7 % -> 0,03 %. '
          + 'Juurisyy 2 (laiskalaatat, musta pilvimainen ja kermanvarinen): ORPO '
          + 'PELILAUDAN z7-LAATTA - linssin avautuessa kesken oleva pelilaudan '
          + 'laattahaku asensi seepialaatan samalla avaimella kuin laastarin uusi laatta, '
          + 'ja poisto purki vain taulun nykyisen olion, joten vanha verkko jai '
          + 'nayttamoon (kankaita 74 / laattoja 72). Korjaus: haku, varalaatta, jono ja '
          + 'vienti tarkistavat laatat.get(avain) === t, vienti vapauttaa orvon; lohko 48 '
          + 'vaatii kankaita <= laattoja, 72/72, 54/54. Sama korjaus kattaa Sonnet 1:n '
          + 'havaitseman kermanvarisen ruudun pelilaudalla Kreikassa (todennetaan '
          + 'laitteella). Julkaistu v1961. JAI: haaleat 1 px aariviivat entisten '
          + 'suorakaiteiden reunoilla; Gronlanti ruskea laastaritilassa (pyramidissa ei '
          + 'jaata) - oma era. LAITEVAHVISTUS (Sonnet 1 kierros 10, v1961, klo 19.04-'
          + '19.13): napa korjaantunut (pehmea Jaameri, ei levya, ei rengasta, ei lohkoja), '
          + 'Wienin loitonnuksen vaalea suorakulmio poissa. JAI: a) Kreetan etelapuolella '
          + 'max-zoomilla kaksi tasaisen tummansinista suorakaidetta ohuine reunoineen ja '
          + 'savyero ymparoivaan mereen (laastarin jaannos) - Opus 2 -era G; b) Kreikan '
          + 'lehdella Thessalonikin pohjoispuoli kermanvarinen ilman reliefia (naapurimaat '
          + 'ilman reliefia, Wienissa reliefi on) - ei orpo laatta vaan reliefirajaus, '
          + 'Opus 2 -era F. TILA F JA G (Opus 2 klo 19.42): F EI VIKA - kerma naapureissa '
