        'KARTTAUUDISTUKSEN PAATOKSET 30: LENTO RAJATAAN LAHTO- JA '
          + 'PAATEPISTEEN MUKAAN, PUNAINEN VIIVA PIIRTYY, PULU POIS (omistaja '
