          + 'hahmo) on POISSA kartalta lennon ajan ja palaa laskeutumisen '
          + 'jalkeen. Tama kumoaa 6.9. linjauksen "kamera seuraa konetta '
          + 'zoomaten" PELIN SISAISTEN lentojen osalta; avauslento (pallo '
          + '-> lahtokaupunki) sailyy ennallaan, ellei omistaja toisin sano. '
          + 'Mitataan: lennon alussa lahto- ja kohdepiste ruudulla '
          + '(molemmat >= 5 % reunasta), viivan pituus kasvaa lennon aikana, '
